// Typed lookups over the presentation catalog (src/lib/wire/catalog.gen.ts,
// generated by ajayeb-gen from the engine's card data). The catalog is
// presentation data: names, colours, printed costs and printed effects for
// display. It never decides what is legal or what anything costs; the
// server's view does.
//
// The lookups take a plain string because slugs arrive from the server as
// strings. They use Object.hasOwn, so a key such as "constructor" or
// "__proto__" is never mistaken for a card.

import {
  cards,
  catalogHash,
  tokens,
  wonders,
  type CardSlug,
  type CatalogCard,
  type CatalogToken,
  type CatalogWonder,
  type TokenSlug,
  type WonderSlug
} from '$lib/wire/catalog.gen';

export {
  cardSlugs,
  catalogHash,
  tokenSlugs,
  wonderSlugs,
  type CardSlug,
  type CatalogCard,
  type CatalogCost,
  type CatalogEffect,
  type CatalogToken,
  type CatalogWonder,
  type DiscountTarget,
  type EffectKind,
  type EffectScope,
  type TokenSlug,
  type WonderSlug
} from '$lib/wire/catalog.gen';

export function isCardSlug(slug: string): slug is CardSlug {
  return Object.hasOwn(cards, slug);
}

export function isWonderSlug(slug: string): slug is WonderSlug {
  return Object.hasOwn(wonders, slug);
}

export function isTokenSlug(slug: string): slug is TokenSlug {
  return Object.hasOwn(tokens, slug);
}

/** The building with this slug, or undefined for an unknown slug. */
export function cardBySlug(slug: string): CatalogCard | undefined {
  return isCardSlug(slug) ? cards[slug] : undefined;
}

/** The wonder with this slug, or undefined for an unknown slug. */
export function wonderBySlug(slug: string): CatalogWonder | undefined {
  return isWonderSlug(slug) ? wonders[slug] : undefined;
}

/** The progress token with this slug, or undefined for an unknown slug. */
export function tokenBySlug(slug: string): CatalogToken | undefined {
  return isTokenSlug(slug) ? tokens[slug] : undefined;
}

/**
 * Whether a view's catalogHash matches the catalog this client was built
 * with. A mismatch means the server plays with other card data, so names,
 * colours and printed effects shown from the catalog may be wrong: the
 * client should ask for a reload.
 */
export function catalogMatches(viewHash: string): boolean {
  return viewHash === catalogHash;
}
